# Новые вузы и колледжи (пункт 4 правок v2): все 8 федеральных округов, профильные вузы.
# Формат: U(id, короткое имя, полное имя, город, регион, домен сайта или None, "коды направлений", ...).
# Домен None — в сайте будет ссылка на поиск Яндекса по названию: мы не смогли проверить адрес из песочницы.
# Проходные баллы и число бюджетных мест для новых программ не заполняем — их показывает DataGap,
# пока не найдены официальные данные (см. scripts/import-tabiturient.ts и data/pass_scores_2026.json).
UNIS = []

def U(id, short, name, city, region, domain, progs, typ="university", dorm=True, vuc=False, budget=True, feat="", emp=0.6,
      pf=170, pt=300, desc="", how="", aliases="", dvi=None):
    codes = progs.split()
    assert len(codes) == len(set(codes)), id
    UNIS.append(dict(id=id, short=short, name=name, city=city, region=region, domain=domain, progs=codes, type=typ, dorm=dorm,
                     vuc=vuc, budget=budget, features=feat.split(), emp=emp, pf=pf, pt=pt, desc=desc, how=how,
                     aliases=aliases.split(",") if aliases else [], dvi=dvi or {}))

